import React from 'react';
import { X } from 'lucide-react';

interface PaymentIframeModalProps {
    url: string;
    isOpen: boolean;
    onClose: () => void;
}

export default function PaymentIframeModal({ url, isOpen, onClose }: PaymentIframeModalProps) {
    if (!isOpen || !url) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in">
            <div className="relative w-full max-w-sm md:max-w-md lg:max-w-lg bg-white rounded-2xl shadow-2xl overflow-hidden flex flex-col h-[85vh]">

                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b border-slate-100 bg-[#F9FAFB]">
                    <h3 className="font-semibold text-slate-700">Secure Checkout</h3>
                    <button
                        onClick={onClose}
                        className="p-1 rounded-full hover:bg-slate-200 text-slate-400 hover:text-slate-600 transition-colors"
                    >
                        <X size={20} />
                    </button>
                </div>

                {/* iFrame Container */}
                <div className="flex-1 bg-white relative">
                    <iframe
                        title="Payment Gateway"
                        src={url}
                        className="absolute inset-0 w-full h-full border-0"
                        allow="payment"
                    />
                </div>
            </div>

            <style jsx>{`
                .animate-fade-in {
                    animation: fadeIn 0.2s ease-out;
                }
                @keyframes fadeIn {
                    from { opacity: 0; }
                    to { opacity: 1; }
                }
            `}</style>
        </div>
    );
}
